component_data_script:
def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

groups = []
try:
	info = {}
	for line in read_rows(props.get("lines")):
		parts = split_row(line, 4)
		info[norm(parts[0])] = {"note": parts[1], "due_date": parts[2], "due_what": parts[3]}
	order = []
	rows_by = {}
	for line in read_rows(props.get("fees")):
		parts = split_row(line, 4)
		if not parts[1]:
			continue
		aud = norm(parts[0])
		if aud not in rows_by:
			rows_by[aud] = []
			order.append(aud)
		rows_by[aud].append({"service": parts[1], "fee": parts[2], "per": parts[3]})
	for aud in order:
		item = info.get(aud) or {}
		groups.append({
			"aud": aud,
			"tag": tag_of(aud),
			"note": item.get("note") or "",
			"rows": rows_by[aud],
			"due_date": item.get("due_date") or "",
			"due_what": item.get("due_what") or "",
		})
except Exception:
	groups = []
component.groups = groups
